#include <vector>

class Solution {
public:
    int minBitwiseOR(std::vector<std::vector<int>>& grid) {
        int ans = (1 << 30) - 1;
        for (int b = 29; b >= 0; --b) {
            int target = ans ^ (1 << b);
            bool possible = true;
            for (const auto& row : grid) {
                bool row_ok = false;
                for (int x : row) {
                    if ((x | target) == target) {
                        row_ok = true;
                        break;
                    }
                }
                if (!row_ok) {
                    possible = false;
                    break;
                }
            }
            if (possible) ans = target;
        }
        return ans;
    }
};

